CREATE FUNCTION private.progression_calendar(_started timestamptz,_ended timestamptz,_asof timestamptz) RETURNS TABLE(sequence integer,starts_at timestamptz,ends_at timestamptz,due_on date) LANGUAGE sql IMMUTABLE SET search_path=public AS $$
 SELECT k,CASE WHEN k=1 THEN _started ELSE private.progression_boundary(_started,k-1) END,private.progression_boundary(_started,k),(private.progression_boundary(_started,k) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-1
 FROM generate_series(1,CASE WHEN (coalesce(_ended,_asof) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date<=(_started AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+5 THEN 1 WHEN (coalesce(_ended,_asof) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date<=(_started AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+12 THEN 2 WHEN (coalesce(_ended,_asof) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date<=(_started AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+19 THEN 3 WHEN (coalesce(_ended,_asof) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date<=(_started AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+26 THEN 4 ELSE 5+(((coalesce(_ended,_asof) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-(_started AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-27)/30) END) k;
$$;
CREATE FUNCTION private.progression_outcome(_ends timestamptz,_ended timestamptz,_note timestamptz,_asof timestamptz) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT CASE WHEN _note IS NOT NULL AND _note<_ends AND _note<=coalesce(_ended,_asof) THEN 'on_time' WHEN _ends<=coalesce(_ended,_asof) THEN 'missed' WHEN _ended IS NOT NULL THEN 'exempt' ELSE 'pending' END; $$;
CREATE FUNCTION private.progression_evaluated() RETURNS TABLE(assignment_id uuid,signal_id uuid,sale_id uuid,sequence integer,starts_at timestamptz,ends_at timestamptz,due_on date,outcome text,note_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT a.id,a.signal_id,a.sale_id,c.sequence,c.starts_at,c.ends_at,c.due_on,
 CASE WHEN p.outcome IN ('on_time','missed') THEN p.outcome ELSE private.progression_outcome(c.ends_at,a.ended_at,n.created_at,now()) END,n.id
 FROM public.signal_progression_assignments a CROSS JOIN LATERAL private.progression_calendar(a.started_at,a.ended_at,now()) c
 LEFT JOIN public.signal_progression_periods p ON p.assignment_id=a.id AND p.sequence=c.sequence
 LEFT JOIN LATERAL (SELECT v.id,v.created_at FROM public.opportunity_signal_notes v WHERE v.signal_id=a.signal_id AND v.created_at>=c.starts_at AND v.created_at<c.ends_at AND v.created_at<=coalesce(a.ended_at,now()) AND public.signal_note_is_progression(v.note,v.event_type,v.is_progression) ORDER BY v.created_at,v.id LIMIT 1) n ON true;
$$;
CREATE OR REPLACE FUNCTION public.signal_progression_deadlines() RETURNS TABLE(signal_id uuid,sale_id uuid,sequence integer,due_on date,deadline_state text,overdue_days integer,next_due_on date,calculated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 WITH active AS (SELECT a.* FROM public.signal_progression_assignments a JOIN public.opportunity_signals s ON s.id=a.signal_id WHERE a.ended_at IS NULL AND private.progression_visible(auth.uid(),s)),
 cur AS (SELECT a.*,c.sequence,c.due_on,c.starts_at,c.ends_at FROM active a CROSS JOIN LATERAL (SELECT * FROM private.progression_calendar(a.started_at,NULL,now()) ORDER BY sequence DESC LIMIT 1) c),
 state AS (SELECT c.*,EXISTS(SELECT 1 FROM public.opportunity_signal_notes n WHERE n.signal_id=c.signal_id AND n.created_at>=c.starts_at AND n.created_at<c.ends_at AND n.created_at<=now() AND public.signal_note_is_progression(n.note,n.event_type,n.is_progression)) AS done,
 (SELECT min(p.ends_at) FROM private.progression_evaluated() p WHERE p.assignment_id=c.id AND p.ends_at<=now() AND p.outcome='missed' AND NOT EXISTS(SELECT 1 FROM public.opportunity_signal_notes n WHERE n.signal_id=c.signal_id AND n.created_at>=p.ends_at AND n.created_at<=now() AND public.signal_note_is_progression(n.note,n.event_type,n.is_progression))) AS backlog FROM cur c)
 SELECT signal_id,sale_id,sequence,due_on,CASE WHEN backlog IS NOT NULL THEN 'overdue' WHEN done THEN 'updated' WHEN due_on=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date THEN 'today' WHEN due_on=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+1 THEN 'soon' ELSE 'ok' END,CASE WHEN backlog IS NULL THEN 0 ELSE greatest(1,(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-(backlog AT TIME ZONE 'Asia/Ho_Chi_Minh')::date+1) END,(private.progression_boundary(started_at,sequence+1) AT TIME ZONE 'Asia/Ho_Chi_Minh')::date-1,now() FROM state;
$$;
CREATE OR REPLACE FUNCTION public.signal_progression_report(_from date DEFAULT NULL,_to date DEFAULT NULL,_sale uuid DEFAULT NULL,_group text DEFAULT NULL,_source text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(private.sig_can(auth.uid(),'signal.report') OR private.sig_can(auth.uid(),'signal.manage'),false) THEN RAISE EXCEPTION 'Không có quyền xem báo cáo'; END IF;
 WITH scope AS (SELECT s.* FROM public.opportunity_signals s WHERE private.progression_visible(auth.uid(),s) AND (_group IS NULL OR _group=ANY(s.need_groups)) AND (_source IS NULL OR s.source=_source)),
 hist AS (SELECT p.sale_id,count(*) FILTER(WHERE p.outcome='on_time') AS on_time,count(*) AS due FROM private.progression_evaluated() p JOIN scope s ON s.id=p.signal_id WHERE p.ends_at<=now() AND p.outcome<>'exempt' AND (_sale IS NULL OR p.sale_id=_sale) AND (_from IS NULL OR p.due_on>=_from) AND (_to IS NULL OR p.due_on<=_to) GROUP BY p.sale_id),
 live AS (SELECT d.sale_id,count(*) AS tracking,count(*) FILTER(WHERE d.deadline_state='overdue') AS overdue,count(*) FILTER(WHERE d.deadline_state='today') AS today,count(*) FILTER(WHERE d.deadline_state='soon') AS soon FROM public.signal_progression_deadlines() d JOIN scope s ON s.id=d.signal_id WHERE (_sale IS NULL OR d.sale_id=_sale) GROUP BY d.sale_id),
 sales AS (SELECT coalesce(h.sale_id,l.sale_id) AS sale_id,coalesce(h.on_time,0) AS on_time,coalesce(h.due,0) AS due,CASE WHEN coalesce(h.due,0)>0 THEN h.on_time*100.0/h.due END AS rate,coalesce(l.tracking,0) AS tracking,coalesce(l.overdue,0) AS overdue,coalesce(l.today,0) AS today,coalesce(l.soon,0) AS soon FROM hist h FULL JOIN live l USING(sale_id))
 SELECT jsonb_build_object('sales',coalesce(jsonb_agg(to_jsonb(sales)),'[]'::jsonb),'total',jsonb_build_object('on_time',coalesce(sum(on_time),0),'due',coalesce(sum(due),0),'rate',CASE WHEN sum(due)>0 THEN sum(on_time)*100.0/sum(due) END,'tracking',coalesce(sum(tracking),0),'overdue',coalesce(sum(overdue),0),'today',coalesce(sum(today),0),'soon',coalesce(sum(soon),0)),'calculated_at',now(),'activated_at',(SELECT activated_at FROM public.signal_progression_config WHERE id)) INTO result FROM sales;
 RETURN result;
END $$;
CREATE FUNCTION public.signal_progression_history(_id uuid) RETURNS TABLE(assignment_id uuid,sale_id uuid,sequence integer,starts_at timestamptz,ends_at timestamptz,due_on date,outcome text,note_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT p.assignment_id,p.sale_id,p.sequence,p.starts_at,p.ends_at,p.due_on,p.outcome,p.note_id FROM private.progression_evaluated() p JOIN public.opportunity_signals s ON s.id=p.signal_id WHERE s.id=_id AND private.progression_visible(auth.uid(),s) ORDER BY p.starts_at DESC,p.sequence DESC;
$$;
REVOKE ALL ON FUNCTION public.signal_progression_history(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.signal_progression_history(uuid) TO authenticated;
REVOKE ALL ON FUNCTION private.progression_calendar(timestamptz,timestamptz,timestamptz),private.progression_outcome(timestamptz,timestamptz,timestamptz,timestamptz),private.progression_evaluated() FROM PUBLIC,anon,authenticated;
COMMENT ON FUNCTION private.progression_evaluated() IS 'Deadline evaluation at read time includes periods created since the last daily reminder; persisted missed outcomes remain immutable.';